package pe.animetv;
import android.content.Intent;import android.view.*;import android.widget.*;import androidx.media3.common.*;import androidx.media3.exoplayer.ExoPlayer;import java.lang.reflect.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.ActivityController;import static org.junit.Assert.*;import static pe.animetv.Models.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,qualifiers="w960dp-h540dp-land-xhdpi")
public class PlayerControlTest {
 public static class FakePlayer extends PlayerActivity {protected Source createSource(){return new TvScreenTest.FakeActivity().createSource();}}
 private FakePlayer activity;private ActivityController<FakePlayer> controller;private long position=10000;private boolean playing=false;
 @Test public void speedPickerPersistsSelectionWithoutSeeking()throws Exception{Method method=PlayerActivity.class.getDeclaredMethod("chooseSpeed");method.setAccessible(true);method.invoke(activity);android.app.AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertNotNull(dialog);assertEquals(8,dialog.getListView().getAdapter().getCount());dialog.getListView().performItemClick(null,5,5);assertEquals(1.5f,new Store(activity).speed(),0);assertEquals(10000,position);new Store(activity).speed(1f);}
 private void set(String name,Object value)throws Exception{Field f=PlayerActivity.class.getDeclaredField(name);f.setAccessible(true);f.set(activity,value);}
 private Object get(String name)throws Exception{Field f=PlayerActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}
 @Test public void timelineHasCurrentTimeLeftAndTotalAtRight()throws Exception{position=750000;((Runnable)get("ticker")).run();TextView current=(TextView)get("clock"),total=(TextView)get("totalClock");assertEquals("12:30",current.getText());assertEquals("25:00",total.getText());Method show=PlayerActivity.class.getDeclaredMethod("showControls",boolean.class);show.setAccessible(true);show.invoke(activity,true);View root=(View)get("root");root.measure(View.MeasureSpec.makeMeasureSpec(1920,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY));root.layout(0,0,1920,1080);LinearLayout times=(LinearLayout)current.getParent();assertTrue(times.getWidth()>1500);assertEquals(0,current.getLeft());assertEquals(times.getWidth(),total.getRight());assertEquals(total.getTop(),current.getTop());}
 @Test public void multipleLanguagesShowAudioChoiceThenOnlyChosenServers()throws Exception{set("servers",List.of(new Server("Voe","sub","SUB"),new Server("Voe","lat","LAT"),new Server("Byse","cast","CAST")));Method choose=PlayerActivity.class.getDeclaredMethod("chooseServer");choose.setAccessible(true);choose.invoke(activity);android.app.Dialog language=org.robolectric.shadows.ShadowDialog.getLatestDialog();View latino=language.getWindow().getDecorView().findViewWithTag("episode-language:LAT");assertNotNull(latino);assertNotNull(language.getWindow().getDecorView().findViewWithTag("episode-language:CAST"));assertNull(language.getWindow().getDecorView().findViewWithTag("episode-server:Voe"));latino.performClick();android.app.Dialog servers=org.robolectric.shadows.ShadowDialog.getLatestDialog();assertFalse(language.isShowing());assertNotNull(servers.getWindow().getDecorView().findViewWithTag("episode-server:Voe"));assertNull(servers.getWindow().getDecorView().findViewWithTag("episode-server:Byse"));assertEquals("LAT",get("episodeLanguage"));servers.dismiss();new Store(activity).language("SUB");}
 @Test public void singleLanguageGoesStraightToServers()throws Exception{set("servers",List.of(new Server("YourUpload","sub","SUB")));Method choose=PlayerActivity.class.getDeclaredMethod("chooseServer");choose.setAccessible(true);choose.invoke(activity);android.app.Dialog servers=org.robolectric.shadows.ShadowDialog.getLatestDialog();assertNotNull(servers.getWindow().getDecorView().findViewWithTag("episode-server:YourUpload"));assertNull(servers.getWindow().getDecorView().findViewWithTag("episode-language:SUB"));servers.dismiss();}
 @Before public void start()throws Exception{Intent intent=new Intent().putStringArrayListExtra("episodes",new ArrayList<>(List.of("https://example.org/1","https://example.org/2","https://example.org/3"))).putStringArrayListExtra("names",new ArrayList<>(List.of("1","2","3"))).putExtra("index",1).putExtra("title","Prueba");controller=Robolectric.buildActivity(FakePlayer.class,intent).setup();activity=controller.get();
  Timeline timeline=new Timeline(){public int getWindowCount(){return 1;}public int getPeriodCount(){return 1;}public Window getWindow(int i,Window w,long p){return w;}public Period getPeriod(int i,Period p,boolean ids){return p;}public int getIndexOfPeriod(Object uid){return 0;}public Object getUidOfPeriod(int i){return "test";}};
  ExoPlayer fake=(ExoPlayer)Proxy.newProxyInstance(ExoPlayer.class.getClassLoader(),new Class<?>[]{ExoPlayer.class},(proxy,method,args)->{switch(method.getName()){case "getCurrentTimeline":return timeline;case "isCommandAvailable":return true;case "getCurrentPosition":return position;case "getDuration":return 1500000L;case "getPlaybackState":return Player.STATE_READY;case "getPlayWhenReady":return playing;case "getCurrentTracks":return Tracks.EMPTY;case "seekTo":if(args.length==1)position=(long)args[0];return null;case "play":playing=true;return null;case "pause":playing=false;return null;default:if(method.getReturnType()==boolean.class)return false;if(method.getReturnType()==int.class)return 0;if(method.getReturnType()==long.class)return 0L;return null;}});set("player",fake);set("firstFrame",false);set("controlsVisible",false);
 }
 @Test public void hiddenTimelineKeepsCurrentTime()throws Exception{position=750000;((Runnable)get("ticker")).run();assertEquals(500,((SeekBar)get("seek")).getProgress());assertTrue(((TextView)get("clock")).getText().toString().startsWith("12:30"));assertEquals(false,get("controlsVisible"));}
 @Test public void headingChangesEpisodeAndToolsHaveAGap()throws Exception{assertEquals("Prueba · 2",((TextView)get("episodeHeading")).getText());Method change=PlayerActivity.class.getDeclaredMethod("changeEpisode",int.class);change.setAccessible(true);change.invoke(activity,2);assertEquals("Prueba · 3",((TextView)get("episodeHeading")).getText());View episodesButton=((LinearLayout)get("actions")).findViewWithTag("Episodios");assertEquals(TvUi.dp(activity,10),((LinearLayout.LayoutParams)episodesButton.getLayoutParams()).leftMargin);}
 @Test public void failedStartupDoesNotEraseResumePosition()throws Exception{Store store=(Store)get("store");store.position("https://example.org/2",300000);position=0;Method m=PlayerActivity.class.getDeclaredMethod("rememberPosition");m.setAccessible(true);m.invoke(activity);assertEquals(300000,store.position("https://example.org/2"));}
 @Test public void watchedAt95PercentPersistsDuringReplay()throws Exception{Store store=(Store)get("store");store.progress("watched",950,1000);assertTrue(store.watched("watched"));assertEquals(950,store.progress("watched"));store.progress("watched",10,1000);assertTrue(store.watched("watched"));}
 @Test public void backgroundKeepsPausedServerAndPosition()throws Exception{set("firstFrame",true);Server server=new Server("Byse","https://example.org/embed","SUB");set("activeServer",server);position=300000;controller.pause();assertEquals(server,get("returningServer"));assertEquals(true,get("returningPaused"));assertEquals(300000,((Store)get("store")).position("https://example.org/2"));}
 @Test public void songButtonUsesConfiguredSeconds()throws Exception{Store store=(Store)get("store");store.seconds("opening",85);Method rebuild=PlayerActivity.class.getDeclaredMethod("rebuildActions");rebuild.setAccessible(true);rebuild.invoke(activity);View song=((LinearLayout)get("actions")).findViewWithTag("song");assertNotNull(song);song.performClick();assertEquals(95000,position);}
 @Test public void playButtonIsCenteredAcrossScreen()throws Exception{Method rebuild=PlayerActivity.class.getDeclaredMethod("rebuildActions");rebuild.setAccessible(true);rebuild.invoke(activity);Method show=PlayerActivity.class.getDeclaredMethod("showControls",boolean.class);show.setAccessible(true);show.invoke(activity,true);FrameLayout root=(FrameLayout)get("root");root.measure(View.MeasureSpec.makeMeasureSpec(1920,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY));root.layout(0,0,1920,1080);View play=(View)get("playButton");int[] at=new int[2],origin=new int[2];play.getLocationOnScreen(at);root.getLocationOnScreen(origin);assertEquals(960,at[0]-origin[0]+play.getWidth()/2,2);}
 @Test public void timelineRemoteUses30SecondsAndConfiguredStep()throws Exception{Method show=PlayerActivity.class.getDeclaredMethod("showControls",boolean.class);show.setAccessible(true);show.invoke(activity,true);View root=(View)get("root");root.measure(View.MeasureSpec.makeMeasureSpec(1920,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY));root.layout(0,0,1920,1080);((SeekBar)get("seek")).requestFocus();assertTrue(((SeekBar)get("seek")).hasFocus());activity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_RIGHT));assertEquals(40000,position);((Store)get("store")).seconds("timeline",20);activity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_LEFT));assertEquals(20000,position);}
 @Test public void serverQualityLabelsOnlyDescribePickerOptions(){assertEquals("Voe - 720p",PlayerActivity.serverCaption(new Server("Voe","test","SUB")));assertEquals("Byse - 1080p",PlayerActivity.serverCaption(new Server("Byse","test","SUB")));assertEquals("MP4Upload - 1080p",PlayerActivity.serverCaption(new Server("MP4Upload","test","SUB")));assertEquals("HLS - 1080p",PlayerActivity.serverCaption(new Server("HLS","test","SUB")));}
 @Test public void newLatanimeDefaultsToAudioAndServerPicker(){assertEquals("ask",new Store(activity).serverDefault("latanime"));}
 @Test public void groupedAudioServerPickerDisplaysLatinoAndCastellanoSeparately()throws Exception{set("servers",List.of(new Server("Voe","test/lat","LAT"),new Server("Voe","test/cast","CAST")));Method method=PlayerActivity.class.getDeclaredMethod("chooseServer");method.setAccessible(true);method.invoke(activity);android.app.Dialog dialog=org.robolectric.shadows.ShadowDialog.getLatestDialog();List<String> labels=new ArrayList<>();for(View view:descendants((ViewGroup)dialog.getWindow().getDecorView()))if(view instanceof TextView)labels.add(((TextView)view).getText().toString());assertTrue(labels.contains("Latino"));assertTrue(labels.contains("Castellano"));dialog.dismiss();}
 @Test public void serverPickerLeavesCloseButtonOutsideScrollableOptions()throws Exception{set("servers",List.of(new Server("Voe","test/voe","SUB"),new Server("Byse","test/byse","SUB"),new Server("MP4Upload","test/mp4","SUB")));Method method=PlayerActivity.class.getDeclaredMethod("chooseServer");method.setAccessible(true);method.invoke(activity);android.app.Dialog dialog=org.robolectric.shadows.ShadowDialog.getLatestDialog();LinearLayout box=(LinearLayout)((ViewGroup)dialog.getWindow().getDecorView().findViewById(android.R.id.content)).getChildAt(0);ScrollView scroll=(ScrollView)box.getChildAt(2);assertEquals(1f,((LinearLayout.LayoutParams)scroll.getLayoutParams()).weight,0);box.measure(View.MeasureSpec.makeMeasureSpec(920,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(700,View.MeasureSpec.EXACTLY));box.layout(0,0,920,700);assertTrue(box.getChildAt(3).getBottom()<=700);dialog.dismiss();}
 @Test public void playbackOptionsUseRightDrawer()throws Exception{Method method=PlayerActivity.class.getDeclaredMethod("playerOptions");method.setAccessible(true);method.invoke(activity);android.app.Dialog dialog=org.robolectric.shadows.ShadowDialog.getLatestDialog();assertEquals(Gravity.RIGHT,dialog.getWindow().getAttributes().gravity);assertEquals(TvUi.dp(activity,360),dialog.getWindow().getAttributes().width);dialog.dismiss();}
 @Test public void serverPickerDisplaysBoth1080Labels()throws Exception{
  set("servers",List.of(new Server("HLS","test/hls","SUB"),new Server("MP4Upload","test/mp4","SUB")));
  Method method=PlayerActivity.class.getDeclaredMethod("chooseServer");method.setAccessible(true);method.invoke(activity);
  android.app.Dialog dialog=org.robolectric.shadows.ShadowDialog.getLatestDialog();
  List<String> labels=new ArrayList<>();
  for(View view:descendants((ViewGroup)dialog.getWindow().getDecorView()))if(view instanceof TextView)labels.add(((TextView)view).getText().toString());
  assertTrue(labels.contains("HLS - 1080p"));assertTrue(labels.contains("MP4Upload - 1080p"));dialog.dismiss();
 }
 @After public void stop(){controller.pause().stop().destroy();}
 @Test public void remoteSeeksWhilePausedWithoutFirstFrame(){activity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_RIGHT));assertEquals(15000,position);activity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_LEFT));assertEquals(10000,position);assertFalse(playing);}
 @Test public void centerTogglesWithoutOpeningControls()throws Exception{activity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_CENTER));assertTrue(playing);assertEquals(false,get("controlsVisible"));}
 private List<View> descendants(ViewGroup group){List<View> out=new ArrayList<>();for(int n=0;n<group.getChildCount();n++){View child=group.getChildAt(n);out.add(child);if(child instanceof ViewGroup)out.addAll(descendants((ViewGroup)child));}return out;}
 @Test public void simplifiedControlsHaveThreeTransportIconsAndEpisodePicker()throws Exception{Method m=PlayerActivity.class.getDeclaredMethod("rebuildActions");m.setAccessible(true);m.invoke(activity);LinearLayout actions=(LinearLayout)get("actions");int icons=0;boolean found=false,episodes=false;for(View v:descendants(actions)){if(!(v instanceof LinearLayout))continue;LinearLayout control=(LinearLayout)v;String label=String.valueOf(control.getContentDescription());if(control.getChildAt(0) instanceof TvUi.Icon)icons++;if(label.startsWith("Adelantar")){control.performClick();found=true;}if(label.equals("Episodios"))episodes=true;assertFalse(label.contains("opening"));assertFalse(label.contains("ending"));}assertEquals(5,icons);assertTrue(episodes);assertTrue(found);assertEquals(15000,position);assertEquals(TvUi.dp(activity,60),((View)get("playButton")).getLayoutParams().height);}
 @Test public void remoteShowsAccumulatedSeekMessage()throws Exception{for(int n=0;n<3;n++)activity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_RIGHT));assertEquals(25000,position);assertEquals("+15 s",((TextView)get("status")).getText());for(int n=0;n<3;n++)activity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_LEFT));assertEquals(10000,position);assertEquals("-15 s",((TextView)get("status")).getText());}
}
